import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Module Resolution — Path-Based Imports + .handl.toml Path Dependencies","description":"","frontmatter":{"title":"Module Resolution — Path-Based Imports + `.handl.toml` Path Dependencies","type":"adr","date":"2026-09-08T00:00:00.000Z","status":"accepted","status_note":"Accepted (amended: unified import model)"},"headers":[],"relativePath":"handl/project/adrs/0096-module-resolution.md","filePath":"vendored/handl/project/adrs/0096-module-resolution.md"}'),a={name:`handl/project/adrs/0096-module-resolution.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0096-module-resolution-—-path-based-imports-handl-toml-path-dependencies" tabindex="-1">ADR-0096: Module Resolution — Path-Based Imports + <code>.handl.toml</code> Path Dependencies <a class="header-anchor" href="#adr-0096-module-resolution-—-path-based-imports-handl-toml-path-dependencies" aria-label="Permalink to “ADR-0096: Module Resolution — Path-Based Imports + .handl.toml Path Dependencies”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Module resolution is <strong>path-based</strong>, with a dependency table as the only indirection. Given <code>import &quot;&lt;spec&gt;&quot;</code>:</p><ol><li><strong>Dependency specifier.</strong> If the first <code>/</code>-separated segment of <code>&lt;spec&gt;</code> names an entry in the project&#39;s <code>.handl.toml</code> <code>[dependencies]</code> table, the remainder resolves inside that package&#39;s directory: <code>import &quot;arrows/fn/map.hnl&quot;</code> → <code>&lt;deps[&quot;arrows&quot;]&gt;/fn/map.hnl</code>. Dependency names shadow same-named directories relative to the module root.</li><li><strong>Relative path.</strong> Otherwise <code>&lt;spec&gt;</code> resolves against the directory of the module currently being loaded (nested imports), falling back to the configured module root, then the process working directory.</li></ol><p><code>[dependencies]</code> maps an import name to a package directory, in either form:</p><div class="language-toml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#888888;--shiki-light:#24292E;">[</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">dependencies</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">]</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">arrows </span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">=</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">vendor/arrows</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;">          #</span><span style="--shiki-dark:#BBBBBB;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;"> bare path</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">utils  </span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">=</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;"> {</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> path </span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">=</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">../shared</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;"> }</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;">   #</span><span style="--shiki-dark:#BBBBBB;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;"> table form (room for future specifiers)</span></span></code></pre></div><p>Paths are relative to the manifest directory (absolute paths honored as-is). The project manifest is discovered by walking up from the entry file&#39;s directory (<code>Kit::discover</code> / <code>Kit::discover_with_eval</code>); the manifest&#39;s directory becomes the module root. With no manifest, the entry directory is the module root and there are no dependencies.</p><p>Only <strong>vendored / path dependencies</strong> are supported — no registry, no network, no version resolution. Registry and content-addressed stores remain the ADR-0010 design and can layer a <code>spec</code>-to-directory resolution step in front of this mechanism without changing import semantics.</p><h3 id="arrow-value-sealing" tabindex="-1">Arrow-value sealing <a class="header-anchor" href="#arrow-value-sealing" aria-label="Permalink to “Arrow-value sealing”">​</a></h3><p>Exported arrow values carry <code>body</code> indices into the <em>module&#39;s</em> AST. Before bindings cross into the importer&#39;s scope, <code>EvalEngine::seal_module_value</code> (a defaulted trait hook — identity for engines whose values carry no ambient-eval references) lets the tree-walk engine register the module&#39;s eval frame (<code>register_home_frame</code>) and stamp un-homed arrows with <code>__home__</code>, the same provenance mechanism <code>HandlFunction</code> already uses.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The <code>import</code> op exists in all three eval engines and <code>handl-runtime</code> owns a <code>ModuleLoader</code> (<code>load_module</code>/<code>resolve_import</code>), but two pieces were missing: a stated resolution policy for the <code>import &quot;path&quot;</code> specifier, and a way for a project to name external packages (<code>.handl.toml</code> had no <code>[dependencies]</code> section). ADR-0010 sketches the long-term package-manager design (content-addressed graph stores, registries, lockfiles) — it is a large design not needed to unblock local development.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><code>import &quot;arrows/fn/map.hnl&quot;</code> works end-to-end via <code>hnl run</code>/<code>hnl eval</code></li><li>A module file is a single top-level statement (Pratt convention); its</li><li><code>from &quot;&lt;name&gt;&quot; import</code> forms still name <em>modules</em> resolved via the</li><li>The <code>loading</code> cycle-detector and the nested-import directory stack are</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>plugin-lib-handl/examples/loader_bench.rs</code> — where this is true.</li><li><code>plugin-ext-refinement</code> — where this is true.</li><li><code>kit-canonical/tests/import_export.rs</code> — where this is true.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0096-module-resolution.html"><code>design/0096-module-resolution.md</code></a>.</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};